请对以下 case 进行三维加权评分。

=== case_id ===
Case-28-veggie-price-001

=== 用户原始指令 (query.txt) ===
帮我搞个菜价卡，数字会变，能点进系统操作，读日程，标已连接

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "帮我搞个菜价卡，数字会变，能点进系统操作，读日程，标已连接",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToIntent",
      "args": {
        "intentName": "ViewCalendarEvent",
        "params": {
          "entityId": "calendar-price-001"
        }
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "calendar": {
        "items": [
          {
            "entityId": {
              "type": "string",
              "description": "菜价提醒日程的唯一标识，用于打开日程详情。",
              "sampleValue": "calendar-price-001"
            },
            "title": {
              "type": "string",
              "description": "菜价比价日程标题，包含当前菜品和会变化的价格数字。",
              "sampleValue": "青菜3.8"
            },
            "description": {
              "type": "string",
              "description": "菜价变化摘要，可展示比昨日或比附近市场的差异。",
              "sampleValue": "比昨日低0.4"
            },
            "dtStart": {
              "type": "string",
              "description": "菜价提醒日程的开始时间或更新时间。",
              "sampleValue": "08:30"
            },
            "dtEnd": {
              "type": "string",
              "description": "菜价提醒日程的结束时间。",
              "sampleValue": "09:00"
            },
            "isServiceValid": {
              "type": "integer",
              "description": "一键服务Link校验状态，2表示校验成功。",
              "sampleValue": 2
            }
          }
        ]
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/calendar_fill.svg",
      "description": "日历实心图标，黑色，适合用于日程读取、日历事件查看和系统日程入口识别。"
    }
  ]
}

